import React, { useState } from "react";
import "./Weather.css";
import SearchForm from "./SearchForm";
import axios from "axios";

export default function Weather(props) {
  let [weatherdata, setWeatherdata] = useState({ ready: false });
  let [city, setCity] = useState("Pretoria");

  function handleResponse(response) {
    console.log(response.data);
    setWeatherdata({
      ready: true,
      temperature: response.data.temperature.current,
      wind: response.data.wind.speed,
      city: response.data.city,
      description: response.data.condition.description,
      iconUrl: response.data.condition.icon_url,
      country: response.data.country,
    });
  }

  function handleSearch(submittedCity) {
    setCity(submittedCity);
    setWeatherdata({ ready: false });
  }

  if (weatherdata.ready) {
    return (
      <div className="weather">
        <SearchForm onSearch={handleSearch} />
        <h1>{weatherdata.city}</h1>
        <ul>
          <li>{weatherdata.country}</li>
          <li>Wednesday 07:00 AM</li>
          <li className="text-capitalize">{weatherdata.description}</li>
        </ul>
        <div className="row">
          <div className="col-6">
            <div className="clearfix">
              <img
                src={weatherdata.iconUrl}
                alt={weatherdata.description}
                className="image float-start"
              />
              <span className="temperature float-start">
                {Math.round(weatherdata.temperature)}
              </span>
              <span className="units float-start">ºC</span>
            </div>
          </div>

          <div className="col-6">
            <ul>
              <li>Precipitation: 15%</li>
              <li>Humidity: 60%</li>
              <li>Wind: {weatherdata.wind} km/h</li>
            </ul>
          </div>
        </div>
      </div>
    );
  } else {
    let apiKey = "bd75f0b07t2b8413f599c23a504017fo";
    let apiUrl = `https://api.shecodes.io/weather/v1/current?query=${city}&key=${apiKey}&units=metric`;
    axios.get(apiUrl).then(handleResponse);

    return "Loading...";
  }
}
